QShader shaderFrom(const unsigned char *data, unsigned int size)
{
    return QShader::fromSerialized(QByteArray(reinterpret_cast<const char *>(data), int(size)));
}

QAtomicInteger<int> g_skipBlendGate { 0 };
QAtomicInteger<int> g_blendFormatsMissing { 0 };
QAtomicInteger<int> g_sampleShadingMissing { 0 };
QAtomicInteger<int> g_transparencyFirstSample { 0 };
QAtomicInteger<int> g_skipBloomPrime { 0 };
QAtomicInteger<int> g_bloomSameTexture { 0 };
QAtomicInteger<int> g_skipStageRelease { 0 };
QAtomicInteger<int> g_skipReadChain { 0 };
QAtomicInteger<int> g_timeDefocusDraws { 0 }; // bit 0: queries; bit 1: boundary-only control (one load at each mark)
QAtomicInteger<qint64> g_defocusTimed { 0 };
QAtomicInteger<qint64> g_gatherGpuNs { 0 };
QAtomicInteger<qint64> g_spritesGpuNs { 0 };
QAtomicInteger<qint64> g_defocusTimeSkipped { 0 };
QAtomicInteger<quint64> g_controlGeneration { 1 };

QAtomicInteger<int> g_bloomChains { 0 };
QAtomicInteger<int> g_defocusSteps { 0 };
QAtomicInteger<int> g_textures { 0 };
QAtomicInteger<qint64> g_bytes { 0 };
QAtomicInteger<int> g_pipelines { 0 };
QAtomicInteger<qint64> g_objectsCreated { 0 };
QAtomicInteger<qint64> g_bloomRecords { 0 };
QAtomicInteger<qint64> g_defocusRecords { 0 };
QAtomicInteger<qint64> g_transparencyResolves { 0 };
QAtomicInteger<qint64> g_generatedMips { 0 };
