QAtomicInteger<qint64> g_stageRecordNs { 0 };

void setControl(QAtomicInteger<int> &control, bool on)
{
    control.storeRelease(on ? 1 : 0);
    g_controlGeneration.fetchAndAddOrdered(1);
}

const char *const kStageNames[] = { "none", "transparency_resolve", "bloom", "defocus", "composite" };
const char *const kFormNames[] = { "overlay", "overlay_glow", "opaque_glow" };

qint64 levelBytes(const QSize &size, int bytesPerTexel)
{
    return qint64(size.width()) * qint64(size.height()) * qint64(bytesPerTexel);
}

// The skipped-release control's objects (the retirement proof's): kept, counted, until a later sync on their QRhi with
// the control off.
struct LeftBehind
{
    QRhi *rhi = nullptr;
    std::shared_ptr<void> objects;
    int count = 0;
};
QMutex g_leftBehindMutex;
QList<LeftBehind> g_leftBehind;

void releaseLeftBehind(QRhi *rhi)
{
    QList<LeftBehind> released;
    {
        QMutexLocker lock(&g_leftBehindMutex);
        for (qsizetype i = g_leftBehind.size() - 1; i >= 0; --i) {
            if (g_leftBehind.at(i).rhi == rhi)
                released.append(g_leftBehind.takeAt(i));
        }
    }
    for (const LeftBehind &left : released)
        g_leftBehindObjects.fetchAndAddRelaxed(-left.count);
    // `released` goes out of scope here, on the render thread, the QRhi alive: the objects are deleted.
}

QRhiGraphicsPipeline::TargetBlend premultipliedOver()
{
    QRhiGraphicsPipeline::TargetBlend b;
    b.enable = true;
    b.srcColor = QRhiGraphicsPipeline::One;
    b.dstColor = QRhiGraphicsPipeline::OneMinusSrcAlpha;
    b.srcAlpha = QRhiGraphicsPipeline::One;
    b.dstAlpha = QRhiGraphicsPipeline::OneMinusSrcAlpha;
    return b;
}

// Light added on colour, the target's alpha kept (passes.py blend_scope's default: colour ONE, ONE; alpha ZERO, ONE).
QRhiGraphicsPipeline::TargetBlend lightAdded()
{
    QRhiGraphicsPipeline::TargetBlend b;
    b.enable = true;
    b.srcColor = QRhiGraphicsPipeline::One;
    b.dstColor = QRhiGraphicsPipeline::One;
    b.srcAlpha = QRhiGraphicsPipeline::Zero;
    b.dstAlpha = QRhiGraphicsPipeline::One;
    return b;
}

QRhiGraphicsPipeline::TargetBlend masked()
{
    QRhiGraphicsPipeline::TargetBlend b;
    b.enable = false;
    b.colorWrite = QRhiGraphicsPipeline::ColorMask();
    return b;
}

