// ------------------------------------------------------------------------------------------------- names and shaders

QString stageKindName(StageKind kind)
{
    return QLatin1String(kStageNames[qBound(0, int(kind), 4)]);
}

bool parseCompositeForm(const QString &text, CompositeForm *out)
{
    for (int i = 0; i < 3; ++i) {
        if (text == QLatin1String(kFormNames[i])) {
            *out = CompositeForm(i);
            return true;
        }
    }
    return false;
}

QString compositeFormName(CompositeForm form)
{
    return QLatin1String(kFormNames[qBound(0, int(form), 2)]);
}

QShader compositeShader(CompositeForm form)
{
    switch (form) {
    case CompositeForm::Overlay:
        return shaderFrom(composite_overlay_frag_qsb, composite_overlay_frag_qsb_size);
    case CompositeForm::OverlayGlow:
        return shaderFrom(composite_overlay_glow_frag_qsb, composite_overlay_glow_frag_qsb_size);
    case CompositeForm::OpaqueGlow:
        return shaderFrom(composite_opaque_glow_frag_qsb, composite_opaque_glow_frag_qsb_size);
    }
    return QShader();
}

QShader transparencyResolveShader(bool multisampled, bool firstSampleControl)
{
    if (!multisampled)
        return shaderFrom(scene_oit_resolve_frag_qsb, scene_oit_resolve_frag_qsb_size);
    if (firstSampleControl)
        return shaderFrom(scene_oit_resolve_sample0_frag_qsb, scene_oit_resolve_sample0_frag_qsb_size);
    return shaderFrom(scene_oit_resolve_samples_frag_qsb, scene_oit_resolve_samples_frag_qsb_size);
}

QShader bloomShader(BloomShader which)
{
    switch (which) {
    case BloomShader::DownFirst:
        return shaderFrom(bloom_down_first_frag_qsb, bloom_down_first_frag_qsb_size);
    case BloomShader::Down:
        return shaderFrom(bloom_down_frag_qsb, bloom_down_frag_qsb_size);
    case BloomShader::Up:
        return shaderFrom(bloom_up_frag_qsb, bloom_up_frag_qsb_size);
    }
    return QShader();
}

QShader defocusShader(DefocusShader which)
{
    switch (which) {
    case DefocusShader::Clip:
        return shaderFrom(defocus_clip_frag_qsb, defocus_clip_frag_qsb_size);
    case DefocusShader::Gather:
        return shaderFrom(defocus_gather_frag_qsb, defocus_gather_frag_qsb_size);
    case DefocusShader::SpritesVertex:
        return shaderFrom(defocus_sprites_vert_qsb, defocus_sprites_vert_qsb_size);
    case DefocusShader::SpritesFragment:
        return shaderFrom(defocus_sprites_frag_qsb, defocus_sprites_frag_qsb_size);
    }
    return QShader();
}

// ------------------------------------------------------------------------------------------------- the gate (D17 point 3)

TransparencyGate transparencyGate(QRhi *rhi, bool multisampled)
{
    TransparencyGate g;
    if (!rhi) {
        g.reason = QStringLiteral("no device");
        return g;
    }
    QString facts;
    if (rhi->backend() == QRhi::Vulkan) {
        // The core's own device facts (QRhi reports PerRenderTargetBlending true on Vulkan whatever the device:
        // research section 8): read once, at the device's creation (vulkan_context.cpp).
        const auto *handles = static_cast<const QRhiVulkanNativeHandles *>(rhi->nativeHandles());
        const QJsonObject device = handles && handles->dev
            ? vulkanDeviceFacts(quint64(reinterpret_cast<quintptr>(handles->dev))) : QJsonObject();
        if (device.isEmpty())
            facts = QStringLiteral("the device's facts are unknown (a Vulkan device the core did not create)");
        const QJsonObject blend = device.value(QStringLiteral("color_attachment_blend")).toObject();
        g.perTargetBlend = device.value(QStringLiteral("independent_blend")).toBool(false);
        g.blendFormats = blend.value(QStringLiteral("rgba16f")).toBool(false)
            && blend.value(QStringLiteral("r16f")).toBool(false);
        g.sampleShading = device.value(QStringLiteral("sample_rate_shading")).toBool(false);
    } else {
        // OpenGL: PerRenderTargetBlending is GL 4.0 (or ES 3.2); GL 3.0+ makes the float formats renderable and
        // blendable (4.6 guarantees both), and per-sample shading is GL 4.0 core. The other backends take QRhi's flag.
        g.perTargetBlend = rhi->isFeatureSupported(QRhi::PerRenderTargetBlending);
        g.blendFormats = true;
        g.sampleShading = g.perTargetBlend;
    }
    if (blendFormatsMissing())
        g.blendFormats = false;               // the harness's control
    if (sampleShadingMissing())
        g.sampleShading = false;
    QStringList missing;
    if (!facts.isEmpty())
        missing.append(facts);
    if (!g.perTargetBlend)
        missing.append(rhi->backend() == QRhi::Vulkan ? QStringLiteral("independentBlend")
                                                      : QStringLiteral("QRhi::PerRenderTargetBlending"));
    if (!g.blendFormats)
        missing.append(QStringLiteral("COLOR_ATTACHMENT_BLEND on RGBA16F and R16F"));
    if (multisampled && !g.sampleShading)
        missing.append(QStringLiteral("sampleRateShading (the per-sample resolve)"));
    g.admitted = missing.isEmpty();
    if (!g.admitted)
        g.reason = QStringLiteral("this device lacks %1").arg(missing.join(QStringLiteral(", ")));
    if (skipBlendGate()) {
        g.admitted = true;                    // the harness's negative control: drawn whatever the device lacks
        g.reason.clear();
    }
    return g;
}

bool perTargetBlendReal(QRhi *rhi, QString *reason)
{
    if (skipBlendGate())
        return true;                          // the harness's negative control (the layer then reports the pipeline)
    if (!rhi) {
        *reason = QStringLiteral("no device");
        return false;
    }
    if (rhi->backend() == QRhi::Vulkan) {
        const auto *handles = static_cast<const QRhiVulkanNativeHandles *>(rhi->nativeHandles());
        const QJsonObject device = handles && handles->dev
            ? vulkanDeviceFacts(quint64(reinterpret_cast<quintptr>(handles->dev))) : QJsonObject();
        if (device.value(QStringLiteral("independent_blend")).toBool(false))
            return true;
        *reason = device.isEmpty()
            ? QStringLiteral("the device's facts are unknown (a Vulkan device the core did not create)")
            : QStringLiteral("this Vulkan device does not enable independentBlend");
        return false;
    }
    if (rhi->isFeatureSupported(QRhi::PerRenderTargetBlending))
        return true;
    *reason = QStringLiteral("this device does not report QRhi::PerRenderTargetBlending");
    return false;
}

// ------------------------------------------------------------------------------------------------- controls and counts

void setSkipBlendGate(bool skip) { setControl(g_skipBlendGate, skip); }
bool skipBlendGate() { return g_skipBlendGate.loadAcquire() != 0; }
void setBlendFormatsMissing(bool missing) { setControl(g_blendFormatsMissing, missing); }
bool blendFormatsMissing() { return g_blendFormatsMissing.loadAcquire() != 0; }
void setSampleShadingMissing(bool missing) { setControl(g_sampleShadingMissing, missing); }
bool sampleShadingMissing() { return g_sampleShadingMissing.loadAcquire() != 0; }
void setTransparencyFirstSample(bool first) { setControl(g_transparencyFirstSample, first); }
bool transparencyFirstSample() { return g_transparencyFirstSample.loadAcquire() != 0; }
void setSkipBloomPrime(bool skip) { setControl(g_skipBloomPrime, skip); }
bool skipBloomPrime() { return g_skipBloomPrime.loadAcquire() != 0; }
void setBloomSameTexture(bool same) { setControl(g_bloomSameTexture, same); }
bool bloomSameTexture() { return g_bloomSameTexture.loadAcquire() != 0; }
void setSkipStageRelease(bool skip) { setControl(g_skipStageRelease, skip); }
bool skipStageRelease() { return g_skipStageRelease.loadAcquire() != 0; }
void setSkipReadChain(bool skip) { setControl(g_skipReadChain, skip); }
bool skipReadChain() { return g_skipReadChain.loadAcquire() != 0; }
static void setDefocusDrawControl(int bit, bool on)
{
    if (on)
        g_timeDefocusDraws.fetchAndOrOrdered(bit);
    else
        g_timeDefocusDraws.fetchAndAndOrdered(~bit);
    g_controlGeneration.fetchAndAddOrdered(1);
}
void setTimeDefocusDraws(bool on) { setDefocusDrawControl(1, on); }
bool timeDefocusDraws() { return (g_timeDefocusDraws.loadAcquire() & 1) != 0; }
void setFlushDefocusDraws(bool on) { setDefocusDrawControl(2, on); }
quint64 stageControlGeneration() { return g_controlGeneration.loadAcquire(); }

StageCounts stageCounts()
{
    StageCounts c;
    c.bloomChains = g_bloomChains.loadRelaxed();
    c.defocusSteps = g_defocusSteps.loadRelaxed();
    c.textures = g_textures.loadRelaxed();
    c.bytes = g_bytes.loadRelaxed();
    c.pipelines = g_pipelines.loadRelaxed();
    c.objectsCreated = g_objectsCreated.loadRelaxed();
    c.bloomRecords = g_bloomRecords.loadRelaxed();
    c.defocusRecords = g_defocusRecords.loadRelaxed();
    c.transparencyResolves = g_transparencyResolves.loadRelaxed();
    c.generatedMips = g_generatedMips.loadRelaxed();
    c.fallbacks = g_fallbacks.loadRelaxed();
    c.leftBehind = g_leftBehindObjects.loadRelaxed();
    c.recordsTimed = g_stageRecordsTimed.loadRelaxed();
    c.recordNs = g_stageRecordNs.loadRelaxed();
    c.defocusTimed = g_defocusTimed.loadRelaxed();
    c.gatherGpuNs = g_gatherGpuNs.loadRelaxed();
    c.spritesGpuNs = g_spritesGpuNs.loadRelaxed();
    c.defocusTimeSkipped = g_defocusTimeSkipped.loadRelaxed();
    return c;
}

void countStageRecordTime(qint64 recordNs)
{
    g_stageRecordsTimed.fetchAndAddRelaxed(1);
    g_stageRecordNs.fetchAndAddRelaxed(recordNs);
}

int defocusReadLevelCap(const QSize &layer)
{
    // The last level made only from even-sized levels (generateMips is the driver's filter on OpenGL and a linear blit on
    // Vulkan: they agree on a halving of an even size and not on an odd one, GL 4.6 section 8.14.4).
    int exact = 0;
    for (QSize s = layer; s.width() > 1 || s.height() > 1; ++exact) {
        if ((s.width() > 1 && s.width() % 2) || (s.height() > 1 && s.height() % 2))
            break;
        s = QSize(qMax(1, s.width() / 2), qMax(1, s.height() / 2));
    }
    return qMax(0, exact - 2);                // the clip's local mean and the sprites' read level + 2
}

void countTransparencyResolve() { g_transparencyResolves.fetchAndAddRelaxed(1); }
void countFallback() { g_fallbacks.fetchAndAddRelaxed(1); }
void countGeneratedMips(int count) { g_generatedMips.fetchAndAddRelaxed(count); }

// ------------------------------------------------------------------------------------------------- the draw timer

#ifdef APIENTRY
#define SRPSS_STAGE_GLAPI APIENTRY
#elif defined(_WIN32)
#define SRPSS_STAGE_GLAPI __stdcall
#else
#define SRPSS_STAGE_GLAPI
#endif

// The timeDefocusDraws control (OpenGL): three timestamps a record (before the gather, between, after the sprites) in a
// ring of slots, each read once its last result is available, never waited for.
struct PostStages::DrawTimer
{
    static constexpr int kSlots = 8;
    using GenQueries = void(SRPSS_STAGE_GLAPI *)(int, unsigned int *);
    using DeleteQueries = void(SRPSS_STAGE_GLAPI *)(int, const unsigned int *);
    using QueryCounter = void(SRPSS_STAGE_GLAPI *)(unsigned int, unsigned int);
    using GetQueryObjectiv = void(SRPSS_STAGE_GLAPI *)(unsigned int, unsigned int, int *);
    using GetQueryObjectui64v = void(SRPSS_STAGE_GLAPI *)(unsigned int, unsigned int, quint64 *);
    GenQueries genQueries = nullptr;
    DeleteQueries deleteQueries = nullptr;
    QueryCounter queryCounter = nullptr;
    GetQueryObjectiv getQueryObjectiv = nullptr;
    GetQueryObjectui64v getQueryObjectui64v = nullptr;
    unsigned int names[kSlots * 3] = {};
    bool pending[kSlots] = {};
    int current = -1;                 // the slot this record marks (-1: none free, the record untimed)
    bool usable = false;
};

namespace {
constexpr unsigned int kGlTimestamp = 0x8E28;
constexpr unsigned int kGlQueryResult = 0x8866;
constexpr unsigned int kGlQueryResultAvailable = 0x8867;
} // namespace

void PostStages::markDefocus(QRhiCommandBuffer *cb, int mark)
{
    // mark 0: before the gather (the slots read back first, a free one taken); 1: between; 2: after the sprites.
    if (!m_rhi || m_rhi->backend() != QRhi::OpenGLES2)
        return;
    const int control = g_timeDefocusDraws.loadAcquire();
    if (!control)
        return;
    if (!(control & 1)) { // same boundaries as the query mode, no queries or result retrieval
        cb->beginExternal();
        cb->endExternal();
        return;
    }
    if (!m_drawTimer) {
        m_drawTimer = std::make_unique<DrawTimer>();
        QOpenGLContext *context = QOpenGLContext::currentContext();
        DrawTimer &t = *m_drawTimer;
        if (context && !context->isOpenGLES()) {
            t.genQueries = reinterpret_cast<DrawTimer::GenQueries>(context->getProcAddress("glGenQueries"));
            t.deleteQueries = reinterpret_cast<DrawTimer::DeleteQueries>(context->getProcAddress("glDeleteQueries"));
            t.queryCounter = reinterpret_cast<DrawTimer::QueryCounter>(context->getProcAddress("glQueryCounter"));
            t.getQueryObjectiv =
                reinterpret_cast<DrawTimer::GetQueryObjectiv>(context->getProcAddress("glGetQueryObjectiv"));
            t.getQueryObjectui64v =
                reinterpret_cast<DrawTimer::GetQueryObjectui64v>(context->getProcAddress("glGetQueryObjectui64v"));
            t.usable = t.genQueries && t.deleteQueries && t.queryCounter && t.getQueryObjectiv && t.getQueryObjectui64v;
            if (t.usable)
                t.genQueries(DrawTimer::kSlots * 3, t.names);
        }
    }
    DrawTimer &t = *m_drawTimer;
    if (!t.usable)
        return;
    cb->beginExternal(); // QRhi's OpenGL backend issues what it recorded first, so the mark lands in order
    if (mark == 0) {
        for (int s = 0; s < DrawTimer::kSlots; ++s) {
            if (!t.pending[s])
                continue;
            int available = 0;
            t.getQueryObjectiv(t.names[s * 3 + 2], kGlQueryResultAvailable, &available);
            if (!available)
                continue;
            quint64 stamps[3] = {};
            for (int q = 0; q < 3; ++q)
                t.getQueryObjectui64v(t.names[s * 3 + q], kGlQueryResult, &stamps[q]);
            g_gatherGpuNs.fetchAndAddRelaxed(qint64(stamps[1] - stamps[0]));
            g_spritesGpuNs.fetchAndAddRelaxed(qint64(stamps[2] - stamps[1]));
            g_defocusTimed.fetchAndAddRelaxed(1);
            t.pending[s] = false;
        }
        t.current = -1;
        for (int s = 0; s < DrawTimer::kSlots && t.current < 0; ++s)
            t.current = t.pending[s] ? -1 : s;
        if (t.current < 0)
            g_defocusTimeSkipped.fetchAndAddRelaxed(1);
    }
    if (t.current >= 0) {
        t.queryCounter(t.names[t.current * 3 + mark], kGlTimestamp);
        if (mark == 2)
            t.pending[t.current] = true;
    }
    cb->endExternal();
}

void PostStages::releaseDrawTimer()
{
    if (!m_drawTimer)
        return;
    if (m_drawTimer->usable && m_rhi && m_rhi->makeThreadLocalNativeContextCurrent())
        m_drawTimer->deleteQueries(DrawTimer::kSlots * 3, m_drawTimer->names);
    m_drawTimer.reset();
}

// ------------------------------------------------------------------------------------------------- the stages' objects

PostStages::PostStages() = default;

PostStages::~PostStages()
{
    release();
}

void PostStages::count(int textures, qint64 bytes, int chains, int steps)
{
    g_textures.fetchAndAddRelaxed(textures);
    g_bytes.fetchAndAddRelaxed(bytes);
    g_bloomChains.fetchAndAddRelaxed(chains);
    g_defocusSteps.fetchAndAddRelaxed(steps);
}

PostStages::Defocus *PostStages::defocusFor(int pass) const
{
    for (int i = 0; i < m_defocusCount; ++i) {
        if (m_defocus[i] && m_defocus[i]->spec.pass == pass)
            return m_defocus[i].get();
    }
    return nullptr;
}

QRhiTexture *PostStages::glow(const QByteArray &step) const
{
    for (int i = 0; i < m_bloomCount; ++i) {
        if (m_blooms[i] && m_blooms[i]->spec.name == step)
            return m_blooms[i]->levels[0].get();
    }
    return nullptr;
}

void PostStages::releaseBloom(Bloom &b)
{
    // The pipelines and bindings first (they name the render pass and the textures), then the targets, the
    // descriptors and the textures.
    b.upAdd.reset();
    b.downRest.reset();
    b.downFirst.reset();
    for (int k = kBloomLevels - 1; k >= 0; --k) {
        b.up[k].reset();
        b.down[k].reset();
    }
    b.sampler.reset();
    int textures = 0;
    for (int k = kBloomLevels - 1; k >= 0; --k) {
        b.targets[k].reset();
        b.passes[k].reset();
        textures += b.levels[k] ? 1 : 0;
        b.levels[k].reset();
    }
    count(-textures, -b.bytes, textures ? -1 : 0, 0);
    b.bytes = 0;
    b.source = nullptr;
}

void PostStages::releaseDefocus(Defocus &d)
{
    d.sprites.reset();
    d.gather.reset();
    d.clip.reset();
    d.spriteBindings.reset();
    d.gatherBindings.reset();
    d.clipBindings.reset();
    d.linearSampler.reset();
    d.mipSampler.reset();
    d.belowTarget.reset();
    d.belowPass.reset();
    const bool held = d.below != nullptr;
    d.below.reset();
    count(held ? -1 : 0, -d.bytes, 0, held ? -1 : 0);
    d.bytes = 0;
    d.belowSize = QSize();
    d.colour = nullptr;
    d.circle = nullptr;
}

bool PostStages::sync(QRhi *rhi, const QList<BloomSpec> &blooms, const QList<DefocusSpec> &defocus,
                      const SceneTargets &targets, QString *error)
{
    if (m_rhi && m_rhi != rhi)
        release();                            // another QRhi: every object again (a node made again)
    m_rhi = rhi;
    // beginExternal requires this declaration. Cached at sync; the dormant product path keeps normal pass flags.
    m_defocusPassFlags = rhi->backend() == QRhi::OpenGLES2 && g_timeDefocusDraws.loadAcquire()
        ? QRhiCommandBuffer::BeginPassFlags(QRhiCommandBuffer::ExternalContent) : QRhiCommandBuffer::BeginPassFlags();
    if (!skipStageRelease())
        releaseLeftBehind(rhi);
    if (blooms.size() > kMaxBloomStages || defocus.size() > kMaxDefocusStages) {
        *error = QStringLiteral("a program has at most %1 bloom and %2 defocus steps").arg(kMaxBloomStages)
                     .arg(kMaxDefocusStages);
        return false;
    }
    // Specs no longer declared (or another program): their objects go (the caller released the pipelines first).
    for (int i = 0; i < kMaxBloomStages; ++i) {
        const bool kept = i < blooms.size() && m_blooms[i] && m_blooms[i]->spec == blooms.at(i);
        if (!kept && m_blooms[i]) {
            releaseBloom(*m_blooms[i]);
            m_blooms[i].reset();
            ++m_objectGeneration;
        }
    }
    m_bloomCount = int(blooms.size());
    for (int i = 0; i < m_bloomCount; ++i) {
        const BloomSpec &spec = blooms.at(i);
        const SceneTargets::Target *source = targets.target(spec.source);
        QRhiTexture *sourceTexture = source && source->ready() ? source->readable(spec.attachment) : nullptr;
        if (!sourceTexture) {
            *error = QStringLiteral("bloom step '%1': its source is not allocated or not readable")
                         .arg(QString::fromLatin1(spec.name));
            return false;
        }
        if (!m_blooms[i]) {
            m_blooms[i] = std::make_unique<Bloom>();
            m_blooms[i]->spec = spec;
        }
        Bloom &b = *m_blooms[i];
        // Python's levels: each max(1, w / 2) of the last, from the source's allocation (post.py BloomChain._allocate).
        QSize sizes[kBloomLevels];
        QSize size = source->allocation;
        for (int k = 0; k < kBloomLevels; ++k) {
            size = QSize(qMax(1, size.width() / 2), qMax(1, size.height() / 2));
            sizes[k] = size;
        }
        bool resized = false;
        for (int k = 0; k < kBloomLevels; ++k)
            resized = resized || sizes[k] != b.sizes[k] || !b.levels[k];
        if (sourceTexture != b.source) {
            b.source = sourceTexture;
            ++m_objectGeneration;             // the first downsample's binding names another texture
        }
        if (!resized)
            continue;
        qint64 bytes = 0;
        int made = 0;
        for (int k = 0; k < kBloomLevels; ++k) {
            const QByteArray label = QByteArrayLiteral("srpss core bloom ") + spec.name + QByteArrayLiteral(" level ")
                + QByteArray::number(k);
            if (!b.levels[k]) {
                b.levels[k].reset(rhi->newTexture(QRhiTexture::RGBA16F, sizes[k], 1,
                                                  QRhiTexture::RenderTarget | QRhiTexture::UsedAsTransferSource));
                b.levels[k]->setName(label);
                ++made;
                g_objectsCreated.fetchAndAddRelaxed(1);
            } else {
                b.levels[k]->setPixelSize(sizes[k]); // the same object at the new size (bindings follow)
            }
            if (!b.levels[k]->create()) {
                *error = QStringLiteral("bloom step '%1': level %2 could not be created at %3 x %4")
                             .arg(QString::fromLatin1(spec.name)).arg(k).arg(sizes[k].width()).arg(sizes[k].height());
                return false;
            }
            if (!b.targets[k]) {
                // One render target a level, keeping its contents (targets.h rule B): an upsample loads it.
                b.targets[k].reset(rhi->newTextureRenderTarget(
                    QRhiTextureRenderTargetDescription(QRhiColorAttachment(b.levels[k].get())),
                    QRhiTextureRenderTarget::PreserveColorContents));
                b.targets[k]->setName(label);
                b.passes[k].reset(b.targets[k]->newCompatibleRenderPassDescriptor());
                b.targets[k]->setRenderPassDescriptor(b.passes[k].get());
                g_objectsCreated.fetchAndAddRelaxed(2);
            }
            if (!b.targets[k]->create()) {
                *error = QStringLiteral("bloom step '%1': level %2's render target could not be created")
                             .arg(QString::fromLatin1(spec.name)).arg(k);
                return false;
            }
            b.sizes[k] = sizes[k];
            bytes += levelBytes(sizes[k], 8);
        }
        count(made, bytes - b.bytes, made == kBloomLevels ? 1 : 0, 0);
        b.bytes = bytes;
        ++m_objectGeneration;
    }
    // The defocus steps: the read level's texture at the near target's allocation and level (D17 choice I).
    for (int i = 0; i < kMaxDefocusStages; ++i) {
        const bool kept = i < defocus.size() && m_defocus[i] && m_defocus[i]->spec.pass == defocus.at(i).pass
            && m_defocus[i]->spec.near == defocus.at(i).near && m_defocus[i]->spec.onto == defocus.at(i).onto;
        if (!kept && m_defocus[i]) {
            releaseDefocus(*m_defocus[i]);
            m_defocus[i].reset();
            ++m_objectGeneration;
        }
    }
    m_defocusCount = int(defocus.size());
    for (int i = 0; i < m_defocusCount; ++i) {
        const DefocusSpec &spec = defocus.at(i);
        const SceneTargets::Target *near = targets.target(spec.near);
        if (!near || !near->ready() || near->decl.colour.size() < 2 || !near->colour[0] || !near->colour[1]) {
            *error = QStringLiteral("defocus step %1: its layer is not allocated").arg(spec.pass);
            return false;
        }
        const QSize layer = near->allocation;
        const int maxLevel = defocusReadLevelCap(layer);
        if (spec.level < 0 || spec.level > maxLevel) {
            // Checked against its resource (the layer's mips): never a read past the levels both backends make alike
            // (the lead, 15 Nov). A refusal is the content's failure, latched and noted once.
            *error = QStringLiteral("defocus step %1: its read level %2 is outside 0 to %3 at %4 x %5 (the clip and the "
                                    "sprites read two levels deeper, and a level made from an odd-sized one is each "
                                    "backend's own filter: D17 as built)")
                         .arg(spec.pass).arg(spec.level).arg(maxLevel).arg(layer.width()).arg(layer.height());
            return false;
        }
        if (!m_defocus[i])
            m_defocus[i] = std::make_unique<Defocus>();
        Defocus &d = *m_defocus[i];
        const QSize below(qMax(1, layer.width() >> spec.level), qMax(1, layer.height() >> spec.level));
        if (d.colour != near->colour[0].get() || d.circle != near->colour[1].get() || d.layerSize != layer) {
            d.colour = near->colour[0].get();
            d.circle = near->colour[1].get();
            d.layerSize = layer;
            ++m_objectGeneration;
        }
        d.spec = spec;
        if (d.below && d.belowSize == below)
            continue;
        const QByteArray label = QByteArrayLiteral("srpss core defocus read level ") + QByteArray::number(spec.pass);
        int made = 0;
        if (!d.below) {
            d.below.reset(rhi->newTexture(QRhiTexture::RGBA16F, below, 1,
                                          QRhiTexture::RenderTarget | QRhiTexture::UsedAsTransferSource));
            d.below->setName(label);
            made = 1;
            g_objectsCreated.fetchAndAddRelaxed(1);
        } else {
            d.below->setPixelSize(below);
        }
        if (!d.below->create()) {
            *error = QStringLiteral("defocus step %1: its read level's texture could not be created at %2 x %3")
                         .arg(spec.pass).arg(below.width()).arg(below.height());
            return false;
        }
        if (!d.belowTarget) {
            d.belowTarget.reset(rhi->newTextureRenderTarget(
                QRhiTextureRenderTargetDescription(QRhiColorAttachment(d.below.get())),
                QRhiTextureRenderTarget::PreserveColorContents));
            d.belowTarget->setName(label);
            d.belowPass.reset(d.belowTarget->newCompatibleRenderPassDescriptor());
            d.belowTarget->setRenderPassDescriptor(d.belowPass.get());
            g_objectsCreated.fetchAndAddRelaxed(2);
        }
        if (!d.belowTarget->create()) {
            *error = QStringLiteral("defocus step %1: its read level's render target could not be created").arg(spec.pass);
            return false;
        }
        const qint64 bytes = levelBytes(below, 8);
        count(made, bytes - d.bytes, 0, made);
        d.bytes = bytes;
        d.belowSize = below;
        ++m_objectGeneration;
    }
    return true;
}

bool PostStages::bloomBindings(Bloom &b)
{
    for (int k = 0; k < kBloomLevels; ++k) {
        QRhiTexture *source = k == 0 ? b.source : b.levels[k - 1].get();
        if (!source || !b.sampler)
            return false;
        if (!b.down[k]) {
            b.down[k].reset(m_rhi->newShaderResourceBindings());
            b.down[k]->setName(QByteArrayLiteral("srpss core bloom down bindings"));
            g_objectsCreated.fetchAndAddRelaxed(1);
        }
        b.down[k]->setBindings({ QRhiShaderResourceBinding::sampledTexture(
            1, QRhiShaderResourceBinding::FragmentStage, source, b.sampler.get()) });
        if (!b.down[k]->create())
            return false;
        if (k == 0)
            continue;
        // up[k] draws into level k - 1 from level k; the harness's control samples the level it draws into (QRhi's
        // "different accesses within the same pass": one texture is tracked whole).
        QRhiTexture *smaller = bloomSameTexture() ? b.levels[k - 1].get() : b.levels[k].get();
        if (!b.up[k]) {
            b.up[k].reset(m_rhi->newShaderResourceBindings());
            b.up[k]->setName(QByteArrayLiteral("srpss core bloom up bindings"));
            g_objectsCreated.fetchAndAddRelaxed(1);
        }
        b.up[k]->setBindings({ QRhiShaderResourceBinding::sampledTexture(
            1, QRhiShaderResourceBinding::FragmentStage, smaller, b.sampler.get()) });
        if (!b.up[k]->create())
            return false;
    }
    return true;
}

bool PostStages::defocusBindings(Defocus &d)
{
    if (!d.colour || !d.circle || !d.below || !d.mipSampler || !d.linearSampler || !m_arena)
        return false;
    const auto block = [this](QRhiShaderResourceBinding::StageFlags stages) {
        return QRhiShaderResourceBinding::uniformBufferWithDynamicOffset(0, stages, m_arena, m_defocusBlockBytes);
    };
    const auto conventions = QRhiShaderResourceBinding::uniformBufferWithDynamicOffset(
        kConventionsBinding, QRhiShaderResourceBinding::FragmentStage, m_arena, m_conventionsBytes);
    const auto fragment = QRhiShaderResourceBinding::FragmentStage;
    const auto vertex = QRhiShaderResourceBinding::VertexStage;
    for (std::unique_ptr<QRhiShaderResourceBindings> *srb : { &d.clipBindings, &d.gatherBindings, &d.spriteBindings }) {
        if (!*srb) {
            srb->reset(m_rhi->newShaderResourceBindings());
            (*srb)->setName(QByteArrayLiteral("srpss core defocus bindings"));
            g_objectsCreated.fetchAndAddRelaxed(1);
        }
    }
    d.clipBindings->setBindings({ block(fragment), conventions,
        QRhiShaderResourceBinding::sampledTexture(1, fragment, d.colour, d.mipSampler.get()),
        QRhiShaderResourceBinding::sampledTexture(2, fragment, d.circle, d.mipSampler.get()) });
    d.gatherBindings->setBindings({ block(fragment), conventions,
        QRhiShaderResourceBinding::sampledTexture(1, fragment, d.colour, d.mipSampler.get()),
        QRhiShaderResourceBinding::sampledTexture(2, fragment, d.circle, d.mipSampler.get()),
        QRhiShaderResourceBinding::sampledTexture(3, fragment, d.below.get(), d.linearSampler.get()) });
    d.spriteBindings->setBindings({ block(vertex),
        QRhiShaderResourceBinding::sampledTexture(1, vertex, d.colour, d.mipSampler.get()),
        QRhiShaderResourceBinding::sampledTexture(2, vertex, d.circle, d.mipSampler.get()) });
    return d.clipBindings->create() && d.gatherBindings->create() && d.spriteBindings->create();
}

bool PostStages::build(QRhi *rhi, const SceneTargets &targets, const QShader &vs, const QRhiVertexInputLayout &layout,
                       QRhiBuffer *arena, quint32 conventionsBytes, quint32 defocusBlockBytes, QString *reason,
                       int *objects)
{
    releasePipelines();
    m_arena = arena;
    m_conventionsBytes = conventionsBytes;
    m_defocusBlockBytes = defocusBlockBytes;
    int made = 0;
    const auto created = [&made](bool ok) {
        made += ok ? 1 : 0;
        return ok;
    };
    const auto finish = [&](bool ok) {
        m_pipelineObjects = made;
        g_pipelines.fetchAndAddRelaxed(made);
        g_objectsCreated.fetchAndAddRelaxed(made);
        *objects += made;
        return ok;
    };
    bool ok = true;
    if (m_bloomCount > 0) {
        const QShader downFirst = bloomShader(BloomShader::DownFirst);
        const QShader down = bloomShader(BloomShader::Down);
        const QShader up = bloomShader(BloomShader::Up);
        if (!downFirst.isValid() || !down.isValid() || !up.isValid()) {
            *reason = QStringLiteral("the bloom shaders do not load");
            return finish(false);
        }
        for (int i = 0; ok && i < m_bloomCount; ++i) {
            Bloom &b = *m_blooms[i];
            const QByteArray label = QByteArrayLiteral("srpss core bloom ") + b.spec.name;
            b.sampler.reset(rhi->newSampler(QRhiSampler::Linear, QRhiSampler::Linear, QRhiSampler::None,
                                            QRhiSampler::ClampToEdge, QRhiSampler::ClampToEdge));
            b.sampler->setName(label + QByteArrayLiteral(" sampler"));
            ok = created(b.sampler->create()) && bloomBindings(b);
            if (!ok) {
                *reason = QStringLiteral("bloom step '%1': its sampler or bindings could not be created")
                              .arg(QString::fromLatin1(b.spec.name));
                break;
            }
            const auto pipeline = [&](std::unique_ptr<QRhiGraphicsPipeline> &p, const QShader &fragment,
                                      const QRhiGraphicsPipeline::TargetBlend &blend, const char *name) {
                p.reset(rhi->newGraphicsPipeline());
                p->setFlags(QRhiGraphicsPipeline::UsesScissor);
                p->setName(label + QByteArray(name));
                p->setTargetBlends({ blend });
                p->setShaderStages({ { QRhiShaderStage::Vertex, vs }, { QRhiShaderStage::Fragment, fragment } });
                p->setVertexInputLayout(layout);
                p->setCullMode(QRhiGraphicsPipeline::None);
                p->setShaderResourceBindings(b.down[0].get()); // every binding set has this layout
                p->setRenderPassDescriptor(b.passes[0].get()); // every level's render pass is compatible (RGBA16F)
                return created(p->create());
            };
            ok = pipeline(b.downFirst, downFirst, QRhiGraphicsPipeline::TargetBlend(), " down first")
                && pipeline(b.downRest, down, QRhiGraphicsPipeline::TargetBlend(), " down")
                && pipeline(b.upAdd, up, lightAdded(), " up");
            if (!ok)
                *reason = QStringLiteral("bloom step '%1': its pipelines could not be created")
                              .arg(QString::fromLatin1(b.spec.name));
        }
    }
    if (ok && m_defocusCount > 0) {
        const QShader clip = defocusShader(DefocusShader::Clip);
        const QShader gather = defocusShader(DefocusShader::Gather);
        const QShader spritesVertex = defocusShader(DefocusShader::SpritesVertex);
        const QShader spritesFragment = defocusShader(DefocusShader::SpritesFragment);
        if (!clip.isValid() || !gather.isValid() || !spritesVertex.isValid() || !spritesFragment.isValid()) {
            *reason = QStringLiteral("the defocus shaders do not load");
            return finish(false);
        }
        for (int i = 0; ok && i < m_defocusCount; ++i) {
            Defocus &d = *m_defocus[i];
            const SceneTargets::Target *onto = targets.target(d.spec.onto);
            if (!onto || !onto->ready() || !onto->renderPass) {
                ok = false;
                *reason = QStringLiteral("defocus step %1: its onto target is not allocated").arg(d.spec.pass);
                break;
            }
            const QByteArray label = QByteArrayLiteral("srpss core defocus ") + QByteArray::number(d.spec.pass);
            // Python's layer sampler: LINEAR_MIPMAP_NEAREST min, LINEAR mag, clamped; the read level's: LINEAR.
            d.mipSampler.reset(rhi->newSampler(QRhiSampler::Linear, QRhiSampler::Linear, QRhiSampler::Nearest,
                                               QRhiSampler::ClampToEdge, QRhiSampler::ClampToEdge));
            d.mipSampler->setName(label + QByteArrayLiteral(" layer sampler"));
            d.linearSampler.reset(rhi->newSampler(QRhiSampler::Linear, QRhiSampler::Linear, QRhiSampler::None,
                                                  QRhiSampler::ClampToEdge, QRhiSampler::ClampToEdge));
            d.linearSampler->setName(label + QByteArrayLiteral(" read level sampler"));
            ok = created(d.mipSampler->create()) && created(d.linearSampler->create()) && defocusBindings(d);
            if (!ok) {
                *reason = QStringLiteral("defocus step %1: its samplers or bindings could not be created").arg(d.spec.pass);
                break;
            }
            // Onto the scene: attachment 0 only (the others masked, as the Python renderer's masks leave them).
            const int attachments = int(onto->decl.colour.size());
            QList<QRhiGraphicsPipeline::TargetBlend> over;
            QList<QRhiGraphicsPipeline::TargetBlend> added;
            for (int a = 0; a < attachments; ++a) {
                over.append(a == 0 ? premultipliedOver() : masked());
                added.append(a == 0 ? lightAdded() : masked());
            }
            d.clip.reset(rhi->newGraphicsPipeline());
            d.clip->setFlags(QRhiGraphicsPipeline::UsesScissor);
            d.clip->setName(label + QByteArrayLiteral(" clip"));
            d.clip->setTargetBlends({ QRhiGraphicsPipeline::TargetBlend() });
            d.clip->setShaderStages({ { QRhiShaderStage::Vertex, vs }, { QRhiShaderStage::Fragment, clip } });
            d.clip->setVertexInputLayout(layout);
            d.clip->setCullMode(QRhiGraphicsPipeline::None);
            d.clip->setShaderResourceBindings(d.clipBindings.get());
            d.clip->setRenderPassDescriptor(d.belowPass.get());
            ok = created(d.clip->create());
            d.gather.reset(rhi->newGraphicsPipeline());
            d.gather->setFlags(QRhiGraphicsPipeline::UsesScissor);
            d.gather->setName(label + QByteArrayLiteral(" gather"));
            d.gather->setTargetBlends(over.cbegin(), over.cend());
            d.gather->setShaderStages({ { QRhiShaderStage::Vertex, vs }, { QRhiShaderStage::Fragment, gather } });
            d.gather->setVertexInputLayout(layout);
            d.gather->setCullMode(QRhiGraphicsPipeline::None);
            d.gather->setSampleCount(onto->samples);
            d.gather->setShaderResourceBindings(d.gatherBindings.get());
            d.gather->setRenderPassDescriptor(onto->renderPass.get());
            ok = ok && created(d.gather->create());
            d.sprites.reset(rhi->newGraphicsPipeline());
            d.sprites->setFlags(QRhiGraphicsPipeline::UsesScissor);
            d.sprites->setName(label + QByteArrayLiteral(" sprites"));
            d.sprites->setTopology(QRhiGraphicsPipeline::TriangleStrip);
            d.sprites->setTargetBlends(added.cbegin(), added.cend());
            d.sprites->setShaderStages({ { QRhiShaderStage::Vertex, spritesVertex },
                                         { QRhiShaderStage::Fragment, spritesFragment } });
            d.sprites->setVertexInputLayout(QRhiVertexInputLayout()); // the corners from the vertex index
            d.sprites->setCullMode(QRhiGraphicsPipeline::None);
            d.sprites->setSampleCount(onto->samples);
            d.sprites->setShaderResourceBindings(d.spriteBindings.get());
            d.sprites->setRenderPassDescriptor(onto->renderPass.get());
            ok = ok && created(d.sprites->create());
            if (!ok)
                *reason = QStringLiteral("defocus step %1: its pipelines could not be created").arg(d.spec.pass);
        }
    }
    return finish(ok);
}

bool PostStages::rebind(const SceneTargets &targets)
{
    Q_UNUSED(targets);
    for (int i = 0; i < m_bloomCount; ++i) {
        if (m_blooms[i] && m_blooms[i]->sampler && !bloomBindings(*m_blooms[i]))
            return false;
    }
    for (int i = 0; i < m_defocusCount; ++i) {
        if (m_defocus[i] && m_defocus[i]->clipBindings && !defocusBindings(*m_defocus[i]))
            return false;
    }
    return true;
}

void PostStages::releasePipelines()
{
    for (int i = 0; i < kMaxBloomStages; ++i) {
        if (!m_blooms[i])
            continue;
        Bloom &b = *m_blooms[i];
        b.upAdd.reset();
        b.downRest.reset();
        b.downFirst.reset();
        for (int k = kBloomLevels - 1; k >= 0; --k) {
            b.up[k].reset();
            b.down[k].reset();
        }
        b.sampler.reset();
    }
    for (int i = 0; i < kMaxDefocusStages; ++i) {
        if (!m_defocus[i])
            continue;
        Defocus &d = *m_defocus[i];
        d.sprites.reset();
        d.gather.reset();
        d.clip.reset();
        d.spriteBindings.reset();
        d.gatherBindings.reset();
        d.clipBindings.reset();
        d.linearSampler.reset();
        d.mipSampler.reset();
    }
    g_pipelines.fetchAndAddRelaxed(-m_pipelineObjects);
    m_pipelineObjects = 0;
    m_arena = nullptr;
}

void PostStages::release()
{
    releasePipelines();
    releaseDrawTimer();                       // before m_rhi goes (its queries are this QRhi's context's)
    if (skipStageRelease() && m_rhi && (m_bloomCount > 0 || m_defocusCount > 0)) {
        // The retirement proof's control: the objects left behind (counted) until a later sync on this QRhi.
        struct Held
        {
            std::unique_ptr<Bloom> blooms[kMaxBloomStages];
            std::unique_ptr<Defocus> defocus[kMaxDefocusStages];
        };
        auto held = std::make_shared<Held>();
        int objects = 0;
        // They leave the stages' counts here (chains, steps, textures, bytes) and are counted as left behind alone, so
        // their release at the later sync settles every count (the retirement proof's audit, 15 Nov).
        for (int i = 0; i < kMaxBloomStages; ++i) {
            if (m_blooms[i]) {
                int textures = 0;
                for (int k = 0; k < kBloomLevels; ++k)
                    textures += m_blooms[i]->levels[k] ? 1 : 0;
                count(-textures, -m_blooms[i]->bytes, textures ? -1 : 0, 0);
            }
            objects += m_blooms[i] ? 3 * kBloomLevels : 0;
            held->blooms[i] = std::move(m_blooms[i]);
        }
        for (int i = 0; i < kMaxDefocusStages; ++i) {
            if (m_defocus[i]) {
                const bool below = m_defocus[i]->below != nullptr;
                count(below ? -1 : 0, -m_defocus[i]->bytes, 0, below ? -1 : 0);
            }
            objects += m_defocus[i] ? 3 : 0;
            held->defocus[i] = std::move(m_defocus[i]);
        }
        LeftBehind left;
        left.rhi = m_rhi;
        left.objects = std::static_pointer_cast<void>(held);
        left.count = objects;
        g_leftBehindObjects.fetchAndAddRelaxed(objects);
        QMutexLocker lock(&g_leftBehindMutex);
        g_leftBehind.append(left);
    } else {
        for (int i = 0; i < kMaxBloomStages; ++i) {
            if (m_blooms[i]) {
                releaseBloom(*m_blooms[i]);
                m_blooms[i].reset();
            }
        }
        for (int i = 0; i < kMaxDefocusStages; ++i) {
            if (m_defocus[i]) {
                releaseDefocus(*m_defocus[i]);
                m_defocus[i].reset();
            }
        }
    }
    m_bloomCount = 0;
    m_defocusCount = 0;
    m_rhi = nullptr;
    m_defocusPassFlags = {};
    ++m_objectGeneration;
}

int PostStages::live() const
{
    int objects = m_pipelineObjects;
    for (int i = 0; i < kMaxBloomStages; ++i) {
        if (!m_blooms[i])
            continue;
        for (int k = 0; k < kBloomLevels; ++k)
            objects += (m_blooms[i]->levels[k] ? 1 : 0) + (m_blooms[i]->targets[k] ? 2 : 0);
    }
    for (int i = 0; i < kMaxDefocusStages; ++i) {
        if (m_defocus[i])
            objects += (m_defocus[i]->below ? 1 : 0) + (m_defocus[i]->belowTarget ? 2 : 0);
    }
    return objects;
}

void PostStages::recordBloom(QRhi *rhi, QRhiCommandBuffer *cb, int pass, const QRhiCommandBuffer::VertexInput &triangle,
                             QRhiResourceUpdateBatch **pending)
{
    Bloom *b = nullptr;
    for (int i = 0; i < m_bloomCount; ++i) {
        if (m_blooms[i] && m_blooms[i]->spec.pass == pass)
            b = m_blooms[i].get();
    }
    if (!b || !b->downFirst || !b->downRest || !b->upAdd)
        return;
    const bool prime = !skipBloomPrime();
    const auto level = [&](int k, QRhiGraphicsPipeline *pipeline, QRhiShaderResourceBindings *bindings) {
        // Rule C: the level was sampled (or read back) since it was last drawn, and its render pass loads it.
        if (prime)
            primeForLoad(rhi, cb, b->levels[k].get());
        cb->beginPass(b->targets[k].get(), QColor(0, 0, 0, 0), { 1.0f, 0 }, *pending);
        *pending = nullptr;
        cb->setGraphicsPipeline(pipeline);
        setViewportAndScissor(cb, QRect(QPoint(), b->sizes[k]));
        cb->setShaderResources(bindings);
        cb->setVertexInput(0, 1, &triangle);
        cb->draw(3);
        cb->endPass();
    };
    // post.py BloomChain.apply: four downsamples (the first with the bright pass), then three upsamples, each added onto
    // the next larger level; the glow is level 0.
    for (int k = 0; k < kBloomLevels; ++k)
        level(k, k == 0 ? b->downFirst.get() : b->downRest.get(), b->down[k].get());
    for (int k = kBloomLevels - 1; k > 0; --k)
        level(k - 1, b->upAdd.get(), b->up[k].get());
    g_bloomRecords.fetchAndAddRelaxed(1);
}

void PostStages::recordDefocusClip(QRhi *rhi, QRhiCommandBuffer *cb, int pass,
                                   const QRhiCommandBuffer::VertexInput &triangle, QRhiResourceUpdateBatch *mips,
                                   quint32 blockOffset, quint32 conventionsOffset)
{
    Defocus *d = defocusFor(pass);
    if (!d || !d->clip) {
        if (mips)
            cb->resourceUpdate(mips);
        return;
    }
    primeForLoad(rhi, cb, d->below.get());
    cb->beginPass(d->belowTarget.get(), QColor(0, 0, 0, 0), { 1.0f, 0 }, mips);
    cb->setGraphicsPipeline(d->clip.get());
    setViewportAndScissor(cb, QRect(QPoint(), d->belowSize));
    const QRhiCommandBuffer::DynamicOffset offsets[2] = { { 0, blockOffset }, { kConventionsBinding, conventionsOffset } };
    cb->setShaderResources(d->clipBindings.get(), 2, offsets);
    cb->setVertexInput(0, 1, &triangle);
    cb->draw(3);
    cb->endPass();
}

void PostStages::recordDefocusOnto(QRhiCommandBuffer *cb, int pass, const QRhiCommandBuffer::VertexInput &triangle,
                                   quint32 blockOffset, quint32 conventionsOffset, bool drawSprites, const QRect &scissor)
{
    Defocus *d = defocusFor(pass);
    if (!d || !d->gather || !d->sprites)
        return;
    // Over the layer's whole allocation, which is the onto target's (both surface-sized): the gather adds nothing where
    // the layer is empty (premultiplied over of zero), and the sprites' clip positions are over the layer's size.
    const QRect whole(QPoint(), d->layerSize);
    const QRhiCommandBuffer::DynamicOffset offsets[2] = { { 0, blockOffset }, { kConventionsBinding, conventionsOffset } };
    markDefocus(cb, 0);                       // the harness's timeDefocusDraws control only (OpenGL)
    cb->setGraphicsPipeline(d->gather.get());
    setViewportAndScissor(cb, whole, scissor);
    cb->setShaderResources(d->gatherBindings.get(), 2, offsets);
    cb->setVertexInput(0, 1, &triangle);
    cb->draw(3);
    markDefocus(cb, 1);
    // The highlight sprites (Python draws them for a radius of half a pixel or more): one per texel of the read level,
    // exactly that level's texels (the count is the core's, D17 choice I).
    if (drawSprites) {
        const quint32 sprites = quint32(d->belowSize.width()) * quint32(d->belowSize.height());
        cb->setGraphicsPipeline(d->sprites.get());
        setViewportAndScissor(cb, whole, scissor);
        cb->setShaderResources(d->spriteBindings.get(), 1, offsets);
        cb->draw(4, sprites);
    }
    markDefocus(cb, 2);
    g_defocusRecords.fetchAndAddRelaxed(1);
}

